  if (!customerResult.ok) throw new Error('Customer not found');

  const customer = customerResult.value;
  const totals = invoiceTotals(invoice);

  const lines = [];

  lines.push(invoice.number ?? 'DRAFT');
  lines.push(customer.name);

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const qtyStr = String(line.qty);
    const nameStr = line.name;
    const unitPriceStr = formatEuros(line.unitPrice);
    const totalStr = formatEuros(total);
    const discountPercent = line.discountPercent ?? 0;

    if (discountPercent > 0) {
      const discount = lineDiscount(line);
      const discountStr = formatEuros(discount);
      const netStr = formatEuros(total - discount);
      lines.push(`${qtyStr} × ${nameStr} @ ${unitPriceStr} = ${totalStr} (${discountPercent}% discount: -${discountStr}) = ${netStr}`);
    } else {
      lines.push(`${qtyStr} × ${nameStr} @ ${unitPriceStr} = ${totalStr}`);
    }
  }

  if (totals.discount > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }

  lines.push(`Total: ${formatEuros(totals.total)}`);

  return lines.join('\n');
}

