import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with valid inputs', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.lines.length, 1);
  assert.deepEqual(result.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 10,
    unitPrice: 8500,
    vatRate: 21,
  });
});

test('createInvoice handles multiple line items', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-05',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 100 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[1].name, 'Logo package');
  assert.equal(result.value.lines[2].name, 'Sticker sheet');
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for invalid date format', () => {
  const invalidDates = ['2026-10-7', '26-10-07', '2026/10/07', '2026-13-01', '2026-02-30', 'not-a-date', '', null, undefined, 2026];
  for (const date of invalidDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, false, `Expected failure for date: ${JSON.stringify(date)}`);
    assert.equal(result.error, 'DATE_INVALID', `Wrong error for date: ${JSON.stringify(date)}`);
  }
});

test('createInvoice accepts valid dates', () => {
  const validDates = ['2026-01-01', '2026-12-31', '2000-02-29', '1900-01-01'];
  for (const date of validDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, true, `Expected success for date: ${date}`);
  }
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports NO_LINES when lines is not an array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: null,
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-integer quantities', () => {
  const invalidQtys = [0, -5, 1.5, 'abc', null, undefined, -0];
  for (const qty of invalidQtys) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty }],
    });
    assert.equal(result.ok, false, `Expected failure for qty: ${JSON.stringify(qty)}`);
    assert.equal(result.error, 'QTY_INVALID', `Wrong error for qty: ${JSON.stringify(qty)}`);
  }
});

test('createInvoice accepts positive integer quantities', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }, { sku: 'DEV-HOUR', qty: 999 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 1);
  assert.equal(result.value.lines[1].qty, 999);
});

test('createInvoice reports UNKNOWN_SKU for products not in catalogue', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input lines', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  const original = JSON.parse(JSON.stringify(lines));
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.deepEqual(lines, original);
});

test('createInvoice products include products with zero VAT rate', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 2 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 0);
  assert.equal(result.value.lines[0].unitPrice, 60000);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 10, unitPrice: 8500 };
  assert.equal(lineTotal(line), 85000);
});

test('lineTotal handles zero and large quantities', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 1000 }), 0);
  assert.equal(lineTotal({ qty: 999, unitPrice: 10000 }), 9990000);
});

test('lineTotal handles fractional cent calculations (all cents are integers anyway)', () => {
  const line = { qty: 3, unitPrice: 100 };
  assert.equal(lineTotal(line), 300);
});

test('invoiceTotals calculates subtotal from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500 },
      { qty: 5, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 47500 + 120000);
  assert.equal(totals.total, 252500);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 60000 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.total, 120000);
});

test('invoiceTotals with empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals does not mutate the invoice', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000 }],
  };
  const original = JSON.parse(JSON.stringify(invoice));
  invoiceTotals(invoice);
  assert.deepEqual(invoice, original);
});

test('invoiceTotals integrates with createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 10 * 8500 + 5 * 9500);
  assert.equal(totals.total, 85000 + 47500);
});

test('addLine adds a new line to a draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
});

test('addLine increases qty if SKU already exists', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 8);
});

test('addLine validates qty like createInvoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const invalidQtys = [0, -5, 1.5, 'abc'];
  for (const qty of invalidQtys) {
    const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty });
    assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' }, `Expected QTY_INVALID for qty: ${JSON.stringify(qty)}`);
  }
});

test('addLine reports UNKNOWN_SKU for missing products', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const result = addLine(invoiceResult.value, { sku: 'UNKNOWN-SKU', qty: 1 });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const nonDraftInvoice = { ...invoiceResult.value, status: 'sent' };
  const result = addLine(nonDraftInvoice, { sku: 'DEV-HOUR', qty: 1 });
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const original = JSON.parse(JSON.stringify(invoiceResult.value));
  addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.deepEqual(invoiceResult.value, original);
});

test('removeLine removes a line from a draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(invoiceResult.ok, true);

  const result = removeLine(invoiceResult.value, 'DES-HOUR');
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND if SKU is missing', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const result = removeLine(invoiceResult.value, 'UNKNOWN-SKU');
  assert.deepEqual(result, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if it would remove the last line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const result = removeLine(invoiceResult.value, 'DES-HOUR');
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(invoiceResult.ok, true);

  const nonDraftInvoice = { ...invoiceResult.value, status: 'sent' };
  const result = removeLine(nonDraftInvoice, 'DES-HOUR');
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(invoiceResult.ok, true);

  const original = JSON.parse(JSON.stringify(invoiceResult.value));
  removeLine(invoiceResult.value, 'DES-HOUR');
  assert.deepEqual(invoiceResult.value, original);
});

test('addLine and removeLine compose correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);
  let invoice = invoiceResult.value;

  const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(addResult.ok, true);
  invoice = addResult.value;
  assert.equal(invoice.lines.length, 2);

  const removeResult = removeLine(invoice, 'DES-HOUR');
  assert.equal(removeResult.ok, true);
  invoice = removeResult.value;
  assert.equal(invoice.lines.length, 1);
  assert.equal(invoice.lines[0].sku, 'DEV-HOUR');
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const result = issueInvoice(invoiceResult.value, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.number, 'INV-2026-0001');
});

test('issueInvoice generates sequential numbers', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const result = issueInvoice(invoiceResult.value, existing);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0003');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedInvoice = { ...invoiceResult.value, status: 'issued' };
  const result = issueInvoice(issuedInvoice, []);
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice preserves all other invoice properties', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(invoiceResult.ok, true);

  const result = issueInvoice(invoiceResult.value, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.lines.length, 2);
  assert.deepEqual(result.value.lines[0].sku, 'DES-HOUR');
});

test('issueInvoice does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const original = JSON.parse(JSON.stringify(invoiceResult.value));
  issueInvoice(invoiceResult.value, []);
  assert.deepEqual(invoiceResult.value, original);
});

test('issueInvoice respects year boundaries in numbering', () => {
  const invoiceResult2025 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-31',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult2025.ok, true);

  const result2025 = issueInvoice(invoiceResult2025.value, ['INV-2025-0050']);
  assert.equal(result2025.ok, true);
  assert.equal(result2025.value.number, 'INV-2025-0051');

  const invoiceResult2026 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
