import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { renderInvoiceText } from '../src/render.js';

test('renderInvoiceText shows DRAFT for unsigned invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);

  const text = renderInvoiceText(result.value);
  assert.match(text, /^DRAFT\n/);
});

test('renderInvoiceText shows invoice number when issued', () => {
  const result = createInvoice({
