  });
  assert.equal(result.ok, true);

  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  assert.match(lines[3], /^Discount: -€42,500\.00$/);
  assert.match(lines[4], /^Total: €0\.00$/);
});

test('renderInvoiceText handles mixed discount and no-discount lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 20 },
      { sku: 'STICKER', qty: 50 },
    ],
  });
  assert.equal(result.ok, true);

  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  assert.match(lines[2], /20% discount:/);
  assert.match(lines[3], /50 × Sticker sheet @ €0\.50 = €25\.00$/);
  assert.match(lines[4], /^Subtotal:/);
  assert.match(lines[5], /^Discount:/);
  assert.match(lines[6], /^Total:/);
});
